const DAY = 86400000;
const mk = (s) => { const [y, m, d] = s.split("-").map(Number); return new Date(y, m - 1, d); };
const isoOf = (dt) => `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}-${String(dt.getDate()).padStart(2, "0")}`;
const todayStart = () => { const n = new Date(); return new Date(n.getFullYear(), n.getMonth(), n.getDate()); };

function dayType(iso, s) {
  const d = mk(iso).getDay();
  const list = (s && s.split) || [];
  let ent = null;
  for (const x of list) if (x && x.from && x.from <= iso) ent = x;
  if (ent && ent.map) { const v = ent.map[d]; return v === "U" || v === "L" ? v : "REST"; }
  if (d === 3) {
    const off = s && s.targets && s.targets.refeedOff;
    return off && iso >= off ? "REST" : "REFEED";
  }
  return d === 1 || d === 4 ? "U" : d === 2 || d === 5 ? "L" : "REST";
}

function dayWeather(s, iso) {
  const flags = [];
  const manual = (s.dayCtx || {})[iso];
  if (manual && manual.est) flags.push({ k: "estimate", why: manual.note || "declared estimate day" });
  if (manual && manual.travel) flags.push({ k: "travel", why: "travel day — interpretation context only, never a trigger" });
  if (manual && manual.illness) flags.push({ k: "illness", why: "illness noted — interpretation context only, never a trigger" });
  (s.events || []).forEach((e) => { const gap = (mk(iso) - mk(e.d)) / DAY; if (gap >= -1 && gap <= 2) flags.push({ k: "event", why: e.t || "event window", pre: gap < 0 }); });
  if (s.blackout && iso <= s.blackout.until && (mk(s.blackout.until) - mk(iso)) / DAY <= 9) flags.push({ k: "sealwater", why: "scale carries event water — sealed window" });
  { const mm2 = (s.medsLog || []).find((x) => x.d === iso); if (mm2 && !mm2.taken) flags.push({ k: "nomeds", why: "no meds this day — appetite, energy, and effort read differently" }); }
  if (dayType(isoOf(new Date(mk(iso).getTime() - DAY)), s) === "REFEED") flags.push({ k: "postrefeed", why: "morning after refeed — storage bump expected" });
  /* R17 — TWO QUESTIONS, TWO ANSWERS. `hard` answers "are this day's FOOD and SCALE
     numbers trustworthy" — a declared estimate day and an event day both fail it, and
     every food/scale consumer keeps reading it unchanged. `hardSession` answers a
     different question: "was the TRAINING itself compromised". A guessed dinner does
     not make 11 reps at 320 less true — the reps were counted at a known load — so the
     estimate flag has no business excluding a session. An EVENT day stays excluded:
     a wedding plausibly does degrade the session, and Joe's ruling left that alone. */
  return { flags, noisy: flags.some((f) => f.k === "estimate" || f.k === "event" || f.k === "sealwater"), hard: flags.some((f) => f.k === "estimate" || (f.k === "event" && !f.pre)), hardSession: flags.some((f) => f.k === "event" && !f.pre), est: flags.some((f) => f.k === "estimate") };
}

function setOneRead(s, exId) {
  const ex9 = (s.exercises || []).find((x) => x && x.id === exId);
  if (!ex9 || typeof ex9.w !== "number") return { status: "IDLE", exId };
  const pts = [];
  for (const d of Object.keys(s.sessionLog || {}).sort()) {
    const sl = s.sessionLog[d];
    const en = (sl.entries || []).find((x) => x && x.id === exId);
    if (!en || !en.reps || !en.reps.length || String(en.w) !== String(ex9.w)) continue;
    let evt = false; try { evt = !!dayWeather(s, d).hardSession; } catch (e) { evt = false; }
    if (evt || paceRushed(sl)) continue;
    pts.push({ d, y: Number(en.reps[0]) || 0 });
  }
  const n = pts.length;
  if (n < TREND_MIN_SESSIONS) return { status: "COUNTING", exId, n, need: TREND_MIN_SESSIONS };
  const ys = pts.map((p) => p.y);
  const my = ys.reduce((a, b) => a + b, 0) / n;
  if (!(my > 0)) return { status: "COUNTING", exId, n: 0, need: TREND_MIN_SESSIONS };
  const mx = (n - 1) / 2;
  let sxx = 0, sxy = 0;
  for (let i = 0; i < n; i++) { sxx += (i - mx) * (i - mx); sxy += (i - mx) * (ys[i] - my); }
  if (!(sxx > 0)) return { status: "COUNTING", exId, n: 0, need: TREND_MIN_SESSIONS };
  const b = sxy / sxx;
  let sse = 0;
  for (let i = 0; i < n; i++) { const yh = my + b * (i - mx); sse += (ys[i] - yh) * (ys[i] - yh); }
  const sePct = Math.max((Math.sqrt(Math.max(sse / (n - 2), 0) / sxx) / my) * 100, TREND_SE_FLOOR);
  const pct = (b / my) * 100;
  const t9 = _tCrit(n - 2);
  return { status: "LIVE", exId, n, pct: +pct.toFixed(3), lo: +(pct - t9 * sePct).toFixed(3), hi: +(pct + t9 * sePct).toFixed(3), from: pts[0].d, to: pts[n - 1].d };
}

function forksOf(s, exId) {
  try {
    const e9 = ((s && s.exercises) || []).find((x) => x && x.id === exId);
    if (!e9) return [];
    if (Array.isArray(e9.forks)) return e9.forks;
    return e9.fork && e9.fork.from ? [e9.fork] : [];   /* pre-V50 shape, read-compatible */
  } catch (e) { return []; }
}

function eraIdx(forks, d) {
  let i = 0;
  for (const f of (forks || [])) { if (f && f.from <= d) i++; }
  return i;
}

function sameEra(forks, d, at) {
  if (!forks || !forks.length) return true;
  return eraIdx(forks, d) === eraIdx(forks, at);
}
